const reclaimProjectMemoryIndexPass = `-- name: ReclaimProjectMemoryIndexPass :execrows
UPDATE project_memory_index
SET phase = ?, pending_commit = ?, branch = ?, last_error = '', updated_at = ?
WHERE project_id = ? AND repo_id = ? AND generation = ? AND phase NOT IN ('idle','failed')
`

type ReclaimProjectMemoryIndexPassParams struct {
	Phase         string
	PendingCommit string
	Branch        string
	UpdatedAt     time.Time
	ProjectID     string
	RepoID        string
	Generation    int64
}

// Resume, or take over, a pass that is still marked in flight.
//
// Conditional on the generation the caller believes is current, so two
// restarts racing to recover the same abandoned pass cannot both proceed: the
// loser's generation is stale by the time it writes. The cursor and counters
// are deliberately NOT reset -- resuming is the point.
func (q *Queries) ReclaimProjectMemoryIndexPass(ctx context.Context, arg ReclaimProjectMemoryIndexPassParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reclaimProjectMemoryIndexPass,
		arg.Phase,
		arg.PendingCommit,
		arg.Branch,
		arg.UpdatedAt,
		arg.ProjectID,
		arg.RepoID,
		arg.Generation,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const touchProjectMemoryItemProvenance = `-- name: TouchProjectMemoryItemProvenance :execrows
UPDATE project_memory_items
SET source_commit = ?, source_digest = ?, source_paths_json = ?,
    generation = ?, state = 'valid', state_reason = '', invalidated_at = NULL
WHERE id = ? AND generation <= ?
`

type TouchProjectMemoryItemProvenanceParams struct {
	SourceCommit    string
	SourceDigest    string
	SourcePathsJson string
	Generation      int64
	ID              string
	Generation_2    int64
}

// Re-confirm a fact whose content did not move: refresh only the provenance
// and the generation, leaving updated_at alone.
//
// Leaving updated_at alone is the whole point. "This fact has not changed
// since March" is information a pack's freshness ranking uses, and a re-index
// that bumped every timestamp would destroy it.
func (q *Queries) TouchProjectMemoryItemProvenance(ctx context.Context, arg TouchProjectMemoryItemProvenanceParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, touchProjectMemoryItemProvenance,
		arg.SourceCommit,
		arg.SourceDigest,
		arg.SourcePathsJson,
		arg.Generation,
		arg.ID,
		arg.Generation_2,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

